// normal apartment: 20-25 C
msg.payload = { temperature: +(20 + Math.random() * 5).toFixed(1) };
// token + host from the container env (Secret iot-credentials / TB_HOST)
const host = env.get('TB_HOST') || 'http://thingsboard:9090';
msg.url = host + '/api/v1/' + env.get('TB_TOKEN_AP1') + '/telemetry';
return msg;

