// heating-oil tank: starts full, burns 5% per tick, refilled when empty
let fuel = flow.get('fuelLevel');
if (fuel === undefined || fuel === null) fuel = 100;
fuel -= 5;
if (fuel < 0) fuel = 100;
flow.set('fuelLevel', fuel);
msg.payload = { fuel: fuel };
// token + host from the container env (Secret iot-credentials / TB_HOST)
const host = env.get('TB_HOST') || 'http://thingsboard:9090';
msg.url = host + '/api/v1/' + env.get('TB_TOKEN_FUEL') + '/telemetry';
return msg;
